#!/usr/bin/env bash
# Passing the enclosing .code-workspace alongside the file is what picks the
# window: the file alone goes to whichever window was focused last, which may
# belong to an unrelated checkout.
set -u

file=$(jq -r '.tool_response.filePath // .tool_input.file_path // empty')
[ -n "$file" ] || exit 0
[ -f "$file" ] || exit 0

dir=$(dirname "$(readlink -f "$file" 2>/dev/null || echo "$file")")

case "$dir/" in
  */dotfiles/* | */dotfiles.*/*) exit 0 ;;
esac

# Only files that are part of a reviewable change: inside a repo, not ignored,
# and not marked generated by the repo's own .gitattributes (linguist-generated,
# or -diff as git itself reads it).
git -C "$dir" rev-parse --is-inside-work-tree >/dev/null 2>&1 || exit 0
! git -C "$dir" check-ignore -q "$file" || exit 0
git -C "$dir" check-attr diff linguist-generated -- "$file" |
  grep -qE ': (linguist-generated: set|diff: unset)$' && exit 0

dir=$(dirname "$file")
workspace=""
while [ "$dir" != "/" ]; do
  for candidate in "$dir"/*.code-workspace; do
    if [ -f "$candidate" ]; then
      workspace="$candidate"
      break 2
    fi
  done
  dir=$(dirname "$dir")
done

# open -g hands the file over without raising VS Code. The `code` CLI has no
# equivalent: it always activates the app.
front_pid=$(osascript -e 'tell application "System Events" to get unix id of first process whose frontmost is true' 2>/dev/null)

if [ -n "$workspace" ]; then
  open -g -a "Visual Studio Code" "$workspace" "$file"
else
  open -g -a "Visual Studio Code" "$file"
fi

# VS Code raises itself anyway when it has to create the window, a second or so
# after the open returns.
[ -n "$front_pid" ] || exit 0
for _ in $(seq 12); do
  sleep 0.15
  [ "$(osascript -e 'tell application "System Events" to get name of first process whose frontmost is true' 2>/dev/null)" = "Code" ] || continue
  osascript -e "tell application \"System Events\" to set frontmost of (first process whose unix id is $front_pid) to true" >/dev/null 2>&1
  break
done
